function canFormPalindrome(s: string): boolean {
  const count = new Array(26).fill(0);
  for (let i = 0; i < s.length; i++) count[s.charCodeAt(i) - 97]++;
  let odd = 0;
  for (const c of count) if (c % 2 === 1) odd++;
  return odd <= 1;
}

